<?php
require dirname(__DIR__).'/scripts/booking-retention-bootstrap.php';list($unused,$db)=booking_retention_cli('gulhouse_db');
$dir=$root.'/.e2e/apartment-unit-location-20261021';$before=json_decode(file_get_contents($dir.'/ciko-before.json'),true);$checks=array();$ck=function($n,$ok)use(&$checks){$checks[]=array('name'=>$n,'status'=>$ok?'PASS':'FAIL');};
foreach($before['tables'] as $t=>$expected){if(in_array($t,array('gh_rooms','gh_properties'),true))continue;$rows=$db->get($t)->result_array();$encoded=array_map('json_encode',$rows);sort($encoded,SORT_STRING);$ck('Business table unchanged: '.$t,count($rows)===$expected['rows']&&hash('sha256',json_encode($encoded))===$expected['sha256']);}
$apt=null;$children=array();$oldProps=array_column($before['properties'],null,'id');foreach($before['properties'] as $p){if($p['code']==='APT')$apt=$p;if(in_array($p['code'],array('APT THE NEST','APT MEJESTIC','APT PIK 2','APT TAMAN ANGGREK'),true))$children[$p['id']]=$p;}
$newRooms=array_column($db->order_by('id')->get('gh_rooms')->result_array(),null,'id');$ck('All existing room IDs retained',array_keys($newRooms)===array_map('intval',array_column($before['rooms'],'id')));
$moved=0;foreach($before['rooms'] as $old){$new=$newRooms[$old['id']]??array();$isApt=isset($children[$old['property_id']]);$equal=true;foreach($old as $k=>$v){$expected=$isApt&&$k==='property_id'?$apt['id']:$v;$equal=$equal&&array_key_exists($k,$new)&&$new[$k]===$expected;}$ck('Room '.$old['id'].' existing fields and timestamps preserved',$equal);if($isApt){$moved++;$child=$children[$old['property_id']];$ck('Unit '.$old['id'].' preserves prior child city/address',array_key_exists('unit_city',$new)&&array_key_exists('unit_address',$new)&&trim((string)$new['unit_city'])===trim((string)$child['city'])&&trim((string)$new['unit_address'])===trim((string)$child['address']));}}
$ck('Exactly five existing units reattached',$moved===5);$props=$db->order_by('id')->get('gh_properties')->result_array();$expectedIds=array_values(array_diff(array_keys($oldProps),array_keys($children)));$actualIds=array_map('intval',array_column($props,'id'));sort($expectedIds);sort($actualIds);$ck('Only four owned child properties removed',count($props)===count($before['properties'])-4&&$expectedIds===$actualIds);
foreach($props as $p){$old=$oldProps[$p['id']]??array();if($p['id']===$apt['id'])$old['is_active']='1';$ck('Property '.$p['id'].' retained with permitted APT activation',$p===$old);}
$ck('Exactly one apartment property active',$db->where('property_type','apartment')->where('is_active',1)->count_all_results('gh_properties')===1);$ck('Five apartment rooms point to shared APT',$db->where('property_id',$apt['id'])->count_all_results('gh_rooms')===5);
$result=array('passed'=>count(array_filter($checks,function($x){return $x['status']==='PASS';})),'failed'=>count(array_filter($checks,function($x){return $x['status']==='FAIL';})),'checks'=>$checks,'database_writes'=>0);file_put_contents($dir.'/ciko-readback-results.json',json_encode($result,JSON_PRETTY_PRINT));echo json_encode($result,JSON_PRETTY_PRINT);exit($result['failed']?1:0);
